import type { Tool, CallToolResult } from '@modelcontextprotocol/sdk/types.js';
import type { TrajectoryDB } from '../db.js';
import { nowISO } from '../db.js';
import type { Discussion, Issue, Task } from '../types.js';
import { normalizeAgent, redactIssue, requireRoles } from '../middleware/agent-scope.js';
import { embedAndStore, topKByCosine } from '../embeddings/store.js';
import { backfillMissing } from '../embeddings/backfill.js';
import { resolveIssueRepo } from './audit.js';
import { toFtsQuery, withFtsGuard } from '../fts-query.js';

type Fn = (args: Record<string, unknown>) => Promise<CallToolResult>;

const ALLOWED_KINDS = new Set(['intent', 'question', 'answer', 'decision', 'note', 'analysis']);

const MAX_BODY_BYTES = 65_536;

const HUMAN_AUTHOR = 'human';

export const HUMAN_AUTHOR_REFUSED =
  "author_forbidden: discussion_append never writes author='human'. Human rows come only from the rework-waiver-capture hook, which records the Human's own prompt. Write the row under your own name and quote the Human verbatim.";

function ok(data: unknown): CallToolResult {
  return { content: [{ type: 'text', text: JSON.stringify(data) }] };
}

function err(message: string): CallToolResult {
  return {
    content: [{ type: 'text', text: JSON.stringify({ error: message }) }],
    isError: true,
  };
}

function requireArg(args: Record<string, unknown>, name: string): unknown {
  if (args[name] === undefined || args[name] === null) {
    throw new Error(`Missing required arg: ${name}`);
  }
  return args[name];
}

function optionalId(args: Record<string, unknown>, name: string): number | null {
  const raw = args[name];
  if (raw === undefined || raw === null || raw === '') return null;
  if (typeof raw === 'number' && Number.isInteger(raw) && raw > 0) return raw;
  if (typeof raw === 'string' && /^[1-9][0-9]*$/.test(raw)) return Number(raw);
  throw new Error(`${name} must be a positive integer id (got ${JSON.stringify(raw)})`);
}

function agentName(name: unknown): string {
  return typeof name === 'string' ? name.toLowerCase().replace(/^tmb:/, '') : '';
}

function wrapHandler(fn: (args: Record<string, unknown>) => Promise<CallToolResult>): Fn {
  return async (args) => {
    try {
      return await fn(args);
    } catch (e) {
      return err((e as Error).message);
    }
  };
}

export function resolveDefaultIssueId(db: TrajectoryDB): number {
  const latest = db.get<{ id: number }>(
    `SELECT id FROM issues WHERE status = 'open' AND id != -1 ORDER BY created_at DESC LIMIT 1`,
  );
  return latest?.id ?? -1;
}

export interface DiscussionEntry {
  issue_id: number | string;
  author: string;
  kind: string;
  body: string;
  created_at?: string;
  repo?: string | null;
  task_id?: number | null;
  supersedes?: number | null;
}

/**
 * The single insert+embed path for discussions. Synchronously INSERTs the row
 * (`repo` defaults to the parent issue's repo) and returns its id, then fires
 * `embedAndStore` for semantic discussion_search. `insertAudit` shares this
 * contract.
 *
 * A row carrying `remote_comment_id` (an ingested PR/MR comment) is deduped on
 * the partial UNIQUE index: when that remote comment is already stored nothing
 * is inserted or embedded and the call returns null.
 *
 * The embed is intentionally NOT awaited: `embed()` yields to the event loop, so
 * the embedding-table write runs in a later turn — after a surrounding
 * synchronous `db.transaction()` callback has returned and COMMIT has executed,
 * making the row visible. The `.catch` keeps an embed failure non-fatal, so it
 * can never roll back a caller's transaction (a failed embed degrades to
 * FTS-only search). Callers inside a transaction therefore get the row id
 * immediately while the embed lands post-commit; callers outside one (e.g.
 * discussion_append) behave identically.
 */
export function insertDiscussion(
  db: TrajectoryDB,
  entry: DiscussionEntry & { remote_comment_id: string },
): number | null;
export function insertDiscussion(db: TrajectoryDB, entry: DiscussionEntry): number;
export function insertDiscussion(
  db: TrajectoryDB,
  entry: DiscussionEntry & { remote_comment_id?: string },
): number | null {
  const createdAt = entry.created_at ?? nowISO();
  const repo = entry.repo ?? resolveIssueRepo(db, entry.issue_id);
  const res = db.run(
    `INSERT INTO discussions (issue_id, author, kind, body, created_at, repo, remote_comment_id, task_id, supersedes)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
     ON CONFLICT (remote_comment_id) WHERE remote_comment_id IS NOT NULL DO NOTHING`,
    [
      entry.issue_id,
      entry.author,
      entry.kind,
      entry.body,
      createdAt,
      repo,
      entry.remote_comment_id ?? null,
      entry.task_id ?? null,
      entry.supersedes ?? null,
    ],
  );
  if (Number(res.changes) === 0) return null;
  const id = Number(res.lastInsertRowid);
  void embedAndStore(db, 'discussions', id, entry.body).catch((e) =>
    console.error('[embeddings] insertDiscussion embed failed:', e),
  );
  return id;
}

export function discussionTools(db: TrajectoryDB): {
  definitions: Tool[];
  handlers: Record<string, Fn>;
} {
  const definitions: Tool[] = [
    {
      name: 'discussion_search',
      description:
        'Search discussions via keyword (FTS5), semantic (cosine), or hybrid (RRF) ranking. Default mode is hybrid. Returns top-K snippets. Use instead of issue_get_with_discussions when you want ranked snippets, not a full dump.',
      inputSchema: {
        type: 'object',
        properties: {
          agent: { type: 'string' },
          query: {
            type: 'string',
            description:
              'Search query. For keyword/hybrid: FTS5 MATCH syntax. For semantic: natural language.',
          },
          mode: {
            type: 'string',
            enum: ['keyword', 'semantic', 'hybrid'],
            description: 'Search mode. Default: hybrid (RRF combines FTS5 + cosine + recency-decay).',
          },
          issue_id: { type: 'string', description: 'Optional — restrict to one issue.' },
          kind: {
            type: 'string',
            enum: ['intent', 'note', 'question', 'answer', 'decision', 'analysis'],
            description: 'Optional — restrict to one discussion kind.',
          },
          k: { type: 'number', description: 'Top-K rows to return. Default 5. Max 20.' },
          recency_alpha: {
            type: 'number',
            description: 'Recency weight 0–1 (hybrid/keyword only). Default 0.3.',
          },
        },
        required: ['agent', 'query'],
      },
    },
    {
      name: 'discussion_append',
      description:
        'Append a discussion entry to an issue. Captures conversational intent, questions, answers, decisions, or notes into the SQLite log. issue_id is optional — defaults to the newest open issue (excluding -1), or -1 if no open issues exist. body is capped at 64 KB; larger payloads return a named validation error.',
      inputSchema: {
        type: 'object',
        properties: {
          agent: { type: 'string', description: 'Caller agent name' },
          issue_id: { type: 'string', description: 'The issue ID (integer as string). Optional — defaults to the newest open issue, else -1.' },
          author: { type: 'string', description: "Author of this entry: an agent name. 'human' is refused; quote the Human verbatim under your own name." },
          kind: {
            type: 'string',
            enum: ['intent', 'question', 'answer', 'decision', 'note', 'analysis'],
            description: 'Entry kind. Default: note',
          },
          body: { type: 'string', description: 'Markdown body of the discussion entry' },
          task_id: {
            type: 'string',
            description:
              "Optional — the task (on this issue) the entry belongs to. That task's task_brief carries its decision/intent rows; an entry without task_id is issue-level.",
          },
          supersedes: {
            type: 'string',
            description:
              'Optional — id of an earlier discussion on this issue that this entry replaces. Only bro or the author of the earlier row may set it. task_brief skips the superseded row; discussion_search still returns it.',
          },
        },
        required: ['agent', 'author', 'body'],
      },
    },
    {
      name: 'discussion_list',
      description:
        'Return discussion entries for an issue ordered by created_at ASC. Supports optional fields projection: pass fields=[\'id\',\'kind\',\'author\',\'body\'] to return only those columns (unknown fields return a named error). Used by bro at session resume and by snapshot generation.',
      inputSchema: {
        type: 'object',
        properties: {
          agent: { type: 'string' },
          issue_id: { type: 'string' },
          limit: { type: 'number', description: 'Max rows to return. Capped at 200. When omitted, returns up to 200 rows (legacy bare-array shape); when provided, response includes next_cursor.' },
          offset: { type: 'number', description: 'Row offset for pagination. Default 0.' },
          cursor: { type: 'string', description: 'Opaque cursor from a previous response. When provided, overrides offset.' },
          fields: {
            type: 'array',
            items: { type: 'string' },
            description: 'Optional column projection. Allowed: id, issue_id, author, kind, body, created_at. Unknown fields return an error. Default: all columns.',
          },
        },
        required: ['agent', 'issue_id'],
      },
    },
    {
      name: 'issue_get_with_discussions',
      description:
        'Convenience call: returns the issue row + its discussion list + its task list in one round-trip. Default compact mode returns counts + last 10 discussions (configurable via last_n). Pass include_full=true to return all discussions (current full behavior). Respects agent-scoped description redaction.',
      inputSchema: {
        type: 'object',
        properties: {
          agent: { type: 'string' },
          issue_id: { type: 'string' },
          include_full: {
            type: 'boolean',
            description: 'When true, return all discussions (no limit). Default false — compact mode returns last_n discussions + total_count.',
          },
          last_n: {
            type: 'number',
            description: 'In compact mode: number of most-recent discussions to return. Default 10. Max 200.',
          },
          limit: { type: 'number', description: 'Deprecated alias for last_n when include_full=false. When include_full=false and limit is provided, acts as last_n cap. Prefer last_n.' },
          cursor: { type: 'string', description: 'Opaque cursor for paginating beyond last_n. When provided, returns next page of discussions.' },
        },
        required: ['agent', 'issue_id'],
      },
    },
  ];

  function decodeCursor(cursor: string): { created_at: string; id: number } | null {
    try {
      return JSON.parse(Buffer.from(cursor, 'base64').toString('utf8')) as {
        created_at: string;
        id: number;
      };
    } catch {
      return null;
    }
  }

  function encodeCursor(row: { created_at: string; id: number }): string {
    return Buffer.from(JSON.stringify({ created_at: row.created_at, id: row.id })).toString(
      'base64',
    );
  }

  const handlers: Record<string, Fn> = {
    discussion_search: wrapHandler(async (args) => {
      normalizeAgent(args['agent'] as string | undefined);
      const query = requireArg(args, 'query') as string;
      const mode = (args['mode'] as string | undefined) ?? 'hybrid';
      const issueId = (args['issue_id'] as string | undefined) ?? null;
      const kind = (args['kind'] as string | undefined) ?? null;
      const k = Math.min(Math.max(1, (args['k'] as number | undefined) ?? 5), 20);
      const alpha = Math.min(1, Math.max(0, (args['recency_alpha'] as number | undefined) ?? 0.3));

      await backfillMissing(db, 'discussions');

      type MatchRow = {
        id: number;
        issue_id: number;
        kind: string;
        author: string;
        created_at: string;
        snippet: string;
        bm25_score: number;
        age_days: number;
      };

      type ResultRow = {
        id: number;
        issue_id: number;
        kind: string;
        author: string;
        created_at: string;
        snippet: string;
        score: number;
      };

      const ftsQuery = toFtsQuery(query);

      const fetchFtsRows = (limitK: number): MatchRow[] =>
        withFtsGuard(() => db.all<MatchRow>(
          `SELECT
             d.id, d.issue_id, d.kind, d.author, d.created_at,
             snippet(discussions_fts, 0, '[', ']', '...', 16) AS snippet,
             bm25(discussions_fts) AS bm25_score,
             (julianday('now') - julianday(d.created_at)) AS age_days
           FROM discussions_fts
           JOIN discussions d ON d.id = discussions_fts.rowid
           WHERE discussions_fts MATCH ?
             AND (? IS NULL OR d.issue_id = CAST(? AS INTEGER))
             AND (? IS NULL OR d.kind = ?)
           ORDER BY bm25(discussions_fts) ASC
           LIMIT ?`,
          [ftsQuery, issueId, issueId, kind, kind, limitK],
        ));

      const fetchRowById = (id: number): MatchRow | undefined =>
        db.get<MatchRow>(
          `SELECT d.id, d.issue_id, d.kind, d.author, d.created_at,
                  '' AS snippet,
                  0.0 AS bm25_score,
                  (julianday('now') - julianday(d.created_at)) AS age_days
           FROM discussions d
           WHERE d.id = ?
             AND (? IS NULL OR d.issue_id = CAST(? AS INTEGER))
             AND (? IS NULL OR d.kind = ?)`,
          [id, issueId, issueId, kind, kind],
        );

      if (mode === 'keyword') {
        const countRow = withFtsGuard(() => db.get<{ n: number }>(
          `SELECT COUNT(*) AS n
           FROM discussions_fts
           JOIN discussions d ON d.id = discussions_fts.rowid
           WHERE discussions_fts MATCH ?
             AND (? IS NULL OR d.issue_id = CAST(? AS INTEGER))
             AND (? IS NULL OR d.kind = ?)`,
          [ftsQuery, issueId, issueId, kind, kind],
        ));
        const total_matched = countRow?.n ?? 0;
        const rows = withFtsGuard(() => db.all<MatchRow>(
          `SELECT
             d.id, d.issue_id, d.kind, d.author, d.created_at,
             snippet(discussions_fts, 0, '[', ']', '...', 16) AS snippet,
             bm25(discussions_fts) AS bm25_score,
             (julianday('now') - julianday(d.created_at)) AS age_days
           FROM discussions_fts
           JOIN discussions d ON d.id = discussions_fts.rowid
           WHERE discussions_fts MATCH ?
             AND (? IS NULL OR d.issue_id = CAST(? AS INTEGER))
             AND (? IS NULL OR d.kind = ?)
           ORDER BY (-bm25_score * (1 - ?) + exp(-age_days / 30.0) * ?) DESC
           LIMIT ?`,
          [ftsQuery, issueId, issueId, kind, kind, alpha, alpha, k],
        ));
        return ok({
          results: rows.map((r) => ({
            id: r.id,
            issue_id: r.issue_id,
            kind: r.kind,
            author: r.author,
            created_at: r.created_at,
            snippet: r.snippet,
            score: -r.bm25_score * (1 - alpha) + Math.exp(-r.age_days / 30) * alpha,
          })),
          total_matched,
        });
      }

      if (mode === 'semantic') {
        const cosineResults = await topKByCosine(db, 'discussions', query, k);
        if (cosineResults.length === 0) {
          return ok({ results: [], total_matched: 0, warning: 'semantic_unavailable' });
        }
        const results: ResultRow[] = [];
        for (const cr of cosineResults) {
          const row = fetchRowById(cr.rowid);
          if (row) {
            results.push({
              id: row.id,
              issue_id: row.issue_id,
              kind: row.kind,
              author: row.author,
              created_at: row.created_at,
              snippet: row.snippet,
              score: cr.score,
            });
          }
        }
        return ok({ results, total_matched: results.length });
      }

      // hybrid: RRF over FTS5 + cosine + recency-decay
      const RRF_K = 60;
      const ftsRows = fetchFtsRows(k * 4);
      const cosineResults = await topKByCosine(db, 'discussions', query, k * 4);
      const semanticAvailable = cosineResults.length > 0;

      const scoreMap = new Map<number, { rrf: number; row: MatchRow }>();

      ftsRows.forEach((r, rank) => {
        const rrf = 1 / (RRF_K + rank + 1);
        const existing = scoreMap.get(r.id);
        if (existing) {
          existing.rrf += rrf;
        } else {
          scoreMap.set(r.id, { rrf, row: r });
        }
      });

      cosineResults.forEach((cr, rank) => {
        const rrf = 1 / (RRF_K + rank + 1);
        const existing = scoreMap.get(cr.rowid);
        if (existing) {
          existing.rrf += rrf;
        } else {
          const row = fetchRowById(cr.rowid);
          if (row) scoreMap.set(cr.rowid, { rrf, row });
        }
      });

      const combined = Array.from(scoreMap.values()).map(({ rrf, row }) => {
        const ageDays = row.age_days;
        const decayed = rrf * (Math.exp(-ageDays / 30) * alpha + (1 - alpha));
        return { row, score: decayed };
      });
      combined.sort((a, b) => b.score - a.score);
      const topRows = combined.slice(0, k);

      const results: ResultRow[] = topRows.map(({ row, score }) => ({
        id: row.id,
        issue_id: row.issue_id,
        kind: row.kind,
        author: row.author,
        created_at: row.created_at,
        snippet: row.snippet,
        score,
      }));

      const response: Record<string, unknown> = { results, total_matched: results.length };
      if (!semanticAvailable) response['warning'] = 'semantic_unavailable';
      return ok(response);
    }),

    discussion_append: requireRoles(
      'discussion_append',
      ['bro', 'swe', 'code-reviewer', 'consultant'],
      wrapHandler(async (args) => {
        normalizeAgent(args['agent'] as string | undefined);
        const rawIssueId = args['issue_id'] as string | undefined;
        const issueId = rawIssueId != null ? rawIssueId : String(resolveDefaultIssueId(db));
        const author = requireArg(args, 'author') as string;
        if (String(author).trim().toLowerCase() === HUMAN_AUTHOR) return err(HUMAN_AUTHOR_REFUSED);
        const body = requireArg(args, 'body') as string;
        const kind = (args['kind'] as string | undefined) ?? 'note';

        const bodyBytes = Buffer.byteLength(body, 'utf8');
        if (bodyBytes > MAX_BODY_BYTES) {
          return err(`body exceeds 64KB limit (${bodyBytes} bytes); truncate before calling discussion_append`);
        }

        if (!ALLOWED_KINDS.has(kind)) {
          return err(
            `Invalid kind: "${kind}". Allowed values: ${[...ALLOWED_KINDS].join(', ')}`,
          );
        }

        if (!author.trim()) {
          throw new Error('author must be a non-empty string');
        }

        const issue = db.get<Issue>('SELECT id FROM issues WHERE id = ?', [issueId]);
        if (!issue) {
          throw new Error(`Not found: issue ${issueId}`);
        }

        const taskId = optionalId(args, 'task_id');
        if (taskId !== null) {
          const task = db.get<{ issue_id: number }>('SELECT issue_id FROM tasks WHERE id = ?', [taskId]);
          if (!task) throw new Error(`Not found: task ${taskId}`);
          if (task.issue_id !== issue.id) {
            throw new Error(`task_id ${taskId} belongs to issue ${task.issue_id}, not issue ${issue.id}`);
          }
        }
        const supersedes = optionalId(args, 'supersedes');
        if (supersedes !== null) {
          const prior = db.get<{ issue_id: number; author: string }>(
            'SELECT issue_id, author FROM discussions WHERE id = ?',
            [supersedes],
          );
          if (!prior) throw new Error(`Not found: discussion ${supersedes}`);
          if (prior.issue_id !== issue.id) {
            throw new Error(`supersedes ${supersedes} belongs to issue ${prior.issue_id}, not issue ${issue.id}`);
          }
          if (normalizeAgent(args['agent']) !== 'bro' && agentName(prior.author) !== agentName(args['agent'])) {
            throw new Error(
              `supersedes_forbidden: only bro or the row's author (${prior.author}) may supersede discussion ${supersedes}`,
            );
          }
        }

        const now = nowISO();
        const id = insertDiscussion(db, {
          issue_id: issueId,
          author,
          kind,
          body,
          created_at: now,
          task_id: taskId,
          supersedes,
        });

        const row = db.get<Discussion>('SELECT * FROM discussions WHERE id = ?', [id]);

        return ok(row);
      }),
    ),

    discussion_list: wrapHandler(async (args) => {
      normalizeAgent(args['agent'] as string | undefined);
      const issueId = requireArg(args, 'issue_id') as string;
      const limitArg = args['limit'] as number | undefined;
      const cursorArg = args['cursor'] as string | undefined;
      const rawOffset = (args['offset'] as number | undefined) ?? 0;
      const fieldsArg = args['fields'] as string[] | undefined;

      const ALLOWED_DISCUSSION_FIELDS = new Set(['id', 'issue_id', 'author', 'kind', 'body', 'created_at']);

      if (fieldsArg !== undefined) {
        const unknown = fieldsArg.filter((f) => !ALLOWED_DISCUSSION_FIELDS.has(f));
        if (unknown.length > 0) {
          return err(`Unknown fields: ${unknown.join(', ')}. Allowed: ${[...ALLOWED_DISCUSSION_FIELDS].join(', ')}`);
        }
      }

      function projectRow(row: Discussion): Record<string, unknown> {
        if (!fieldsArg) return row as unknown as Record<string, unknown>;
        const out: Record<string, unknown> = {};
        for (const f of fieldsArg) out[f] = (row as unknown as Record<string, unknown>)[f];
        return out;
      }

      const issue = db.get<{ id: number }>('SELECT id FROM issues WHERE id = ?', [issueId]);
      if (!issue) {
        return ok({ discussions: [], warning: 'issue not found' });
      }

      if (limitArg === undefined || limitArg === null) {
        const offset = Math.max(0, rawOffset);
        const rows = db.all<Discussion>(
          `SELECT * FROM discussions WHERE issue_id = ? ORDER BY created_at ASC LIMIT 200 OFFSET ?`,
          [issueId, offset],
        );
        return ok(rows.map(projectRow));
      }

      const limit = Math.min(Math.max(1, limitArg), 200);
      let cursorFilter = '';
      let cursorParams: unknown[] = [];

      if (cursorArg) {
        const decoded = decodeCursor(cursorArg);
        if (decoded) {
          cursorFilter =
            'AND (created_at > ? OR (created_at = ? AND id > ?))';
          cursorParams = [decoded.created_at, decoded.created_at, decoded.id];
        }
      }

      const sql =
        'SELECT * FROM discussions WHERE issue_id = ? ' +
        cursorFilter +
        ' ORDER BY created_at ASC, id ASC LIMIT ?';
      const fetchedRows = db.all<Discussion>(sql, [issueId, ...cursorParams, limit + 1]);

      const hasMore = fetchedRows.length > limit;
      const rows = hasMore ? fetchedRows.slice(0, limit) : fetchedRows;
      const last = rows[rows.length - 1];
      const next_cursor = hasMore && last ? encodeCursor(last) : undefined;

      return ok({ rows: rows.map(projectRow), next_cursor });
    }),

    issue_get_with_discussions: wrapHandler(async (args) => {
      const agent = normalizeAgent(args['agent'] as string | undefined);
      const issueId = requireArg(args, 'issue_id') as string;
      const includeFull = (args['include_full'] as boolean | undefined) ?? false;
      const lastNArg = (args['last_n'] as number | undefined);
      // legacy: `limit` acts as last_n when include_full=false
      const limitArg = args['limit'] as number | undefined;
      const cursorArg = args['cursor'] as string | undefined;

      const issue = db.get<Issue>('SELECT * FROM issues WHERE id = ?', [issueId]);
      if (!issue) {
        throw new Error(`Not found: issue ${issueId}`);
      }

      const tasks = db.all<Pick<Task, 'id' | 'branch_id' | 'status' | 'title'>>(
        `SELECT id, branch_id, status, title FROM tasks WHERE issue_id = ? ORDER BY branch_id ASC`,
        [issueId],
      );

      const redactedIssue = redactIssue(issue, agent);

      if (includeFull) {
        const discussions = db.all<Discussion>(
          `SELECT * FROM discussions WHERE issue_id = ? ORDER BY created_at ASC`,
          [issueId],
        );
        return ok({ issue: redactedIssue, discussions, tasks });
      }

      // Compact mode: return counts + last N discussions
      const totalCount = (db.get<{ n: number }>(
        `SELECT COUNT(*) AS n FROM discussions WHERE issue_id = ?`,
        [issueId],
      ))?.n ?? 0;

      const resolvedLastN = Math.min(
        Math.max(1, lastNArg ?? limitArg ?? 10),
        200,
      );

      let cursorFilter = '';
      let cursorParams: unknown[] = [];

      if (cursorArg) {
        const decoded = decodeCursor(cursorArg);
        if (decoded) {
          // DESC pagination walks toward older rows, so the next page is
          // everything strictly older than the last row we returned.
          cursorFilter = 'AND (created_at < ? OR (created_at = ? AND id < ?))';
          cursorParams = [decoded.created_at, decoded.created_at, decoded.id];
        }
      }

      const sql =
        'SELECT * FROM discussions WHERE issue_id = ? ' +
        cursorFilter +
        ' ORDER BY created_at DESC, id DESC LIMIT ?';
      const fetchedDisc = db.all<Discussion>(sql, [issueId, ...cursorParams, resolvedLastN + 1]);

      const hasMore = fetchedDisc.length > resolvedLastN;
      const sliced = hasMore ? fetchedDisc.slice(0, resolvedLastN) : fetchedDisc;
      // fetchedDisc is DESC (newest first); the oldest returned row is the last
      // element. Capture it for the next cursor BEFORE reversing for display.
      const oldest = sliced[sliced.length - 1];
      const next_cursor = hasMore && oldest ? encodeCursor(oldest) : undefined;
      // Return in ascending order for readability (copy so the cursor above is
      // not affected by the in-place reverse).
      const discussions = sliced.slice().reverse();

      return ok({
        issue: redactedIssue,
        discussions,
        tasks,
        total_discussion_count: totalCount,
        returned_count: discussions.length,
        ...(next_cursor !== undefined ? { next_cursor } : {}),
      });
    }),
  };

  return { definitions, handlers };
}
