/**
 * The closed set of `audit.event_type` values. Every audit writer — server
 * (`insertAudit`, `audit_append`), hooks (`tmb_audit_append` / `tmb_audit_sql`
 * via the generated `scripts/hooks/lib/audit-events.txt`) and the
 * `audit.event_type` section of `docs/contributing/ENUMS.md` — derives from
 * this list. `reserved` marks an event no code literal writes: an agent records
 * it through `audit_append`, or it is a legacy type kept for historical rows.
 *
 * `writers` names who may author the event: an agent role (the role of the
 * role-gated tool whose handler writes it, or the agent that records it
 * through `audit_append`), `server` (a server path no role gates: a migration,
 * an ungated handler), or `hook` (a hook or script through the hook write
 * library). `audit_append` admits a caller only when its role is listed;
 * `tmb_audit_append` admits a hook only when `hook` is listed.
 */
export type Writer = 'bro' | 'swe' | 'code-reviewer' | 'consultant' | 'server' | 'hook';

export interface AuditEventDef {
  readonly type: string;
  readonly writers: readonly Writer[];
  readonly description: string;
  readonly reserved?: true;
}

