export type AuditEventType = (typeof AUDIT_EVENT_TYPES)[number]['type'];

const KNOWN: ReadonlySet<string> = new Set(AUDIT_EVENT_TYPES.map((e) => e.type));
const WRITERS: ReadonlyMap<string, readonly Writer[]> = new Map(AUDIT_EVENT_TYPES.map((e) => [e.type, e.writers]));

export function isAuditEventType(value: unknown): value is AuditEventType {
  return typeof value === 'string' && KNOWN.has(value);
}

export function auditEventWriters(type: AuditEventType): readonly Writer[] {
  return WRITERS.get(type) ?? [];
}

export function isAuditEventWritableBy(type: AuditEventType, writer: Writer): boolean {
  return auditEventWriters(type).includes(writer);
}

export function assertAuditEventType(value: unknown): AuditEventType {
  if (isAuditEventType(value)) return value;
  throw new Error(
    `unknown audit event_type '${String(value)}'. Allowed: ${AUDIT_EVENT_TYPES.map((e) => e.type).join(', ')}`,
  );
}
